const commits = $('GitHub Commits').all().flatMap(item => Array.isArray(item.json) ? item.json : [item.json]);
const issues = $('GitHub Closed Issues').all().flatMap(item => Array.isArray(item.json) ? item.json : [item.json]);
const prs = $('GitHub Merged PRs').all().flatMap(item => Array.isArray(item.json) ? item.json : [item.json]);

const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
const mergedPRs = prs.filter(pr => pr.merged_at && new Date(pr.merged_at) >= weekAgo);

const formatDate = (d) => new Date(d).toISOString().split('T')[0];
const lang = $('Config').item.json.LANGUAGE || 'EN';

let report = '';
if (lang === 'FR') {
  report = `RÉSUMÉ HEBDOMADAIRE DE DÉVELOPPEMENT\nDépôt: ${$('Config').item.json.GITHUB_REPO}\nPériode: 7 derniers jours\n\n`;
  report += `## COMMITS (${commits.length})\n`;
  if (commits.length === 0) report += 'Aucun commit cette semaine.\n';
  else commits.slice(0, 30).forEach(c => {
    const sha = (c.sha || '').substring(0, 7);
    const msg = (c.commit && c.commit.message || '').split('\n')[0];
    const author = c.commit && c.commit.author ? c.commit.author.name : 'inconnu';
    const date = c.commit && c.commit.author ? formatDate(c.commit.author.date) : '';
    report += `- [${sha}] ${msg} (${author}, ${date})\n`;
  });
  report += `\n## TICKETS FERMÉS (${issues.length})\n`;
  if (issues.length === 0) report += 'Aucun ticket fermé cette semaine.\n';
  else issues.slice(0, 20).forEach(i => {
    const labels = i.labels ? i.labels.map(l => l.name).join(', ') : '';
    report += `- #${i.number}: ${i.title}${labels ? ' [' + labels + ']' : ''}\n`;
  });
  report += `\n## PULL REQUESTS MERGÉES (${mergedPRs.length})\n`;
  if (mergedPRs.length === 0) report += 'Aucune PR mergée cette semaine.\n';
  else mergedPRs.slice(0, 20).forEach(p => {
    report += `- #${p.number}: ${p.title} (par ${p.user ? p.user.login : 'inconnu'})\n`;
  });
} else {
  report = `WEEKLY DEV SUMMARY\nRepository: ${$('Config').item.json.GITHUB_REPO}\nPeriod: Last 7 days\n\n`;
  report += `## COMMITS (${commits.length})\n`;
  if (commits.length === 0) report += 'No commits this week.\n';
  else commits.slice(0, 30).forEach(c => {
    const sha = (c.sha || '').substring(0, 7);
    const msg = (c.commit && c.commit.message || '').split('\n')[0];
    const author = c.commit && c.commit.author ? c.commit.author.name : 'unknown';
    const date = c.commit && c.commit.author ? formatDate(c.commit.author.date) : '';
    report += `- [${sha}] ${msg} (${author}, ${date})\n`;
  });
  report += `\n## CLOSED ISSUES (${issues.length})\n`;
  if (issues.length === 0) report += 'No closed issues this week.\n';
  else issues.slice(0, 20).forEach(i => {
    const labels = i.labels ? i.labels.map(l => l.name).join(', ') : '';
    report += `- #${i.number}: ${i.title}${labels ? ' [' + labels + ']' : ''}\n`;
  });
  report += `\n## MERGED PULL REQUESTS (${mergedPRs.length})\n`;
  if (mergedPRs.length === 0) report += 'No merged PRs this week.\n';
  else mergedPRs.slice(0, 20).forEach(p => {
    report += `- #${p.number}: ${p.title} (by ${p.user ? p.user.login : 'unknown'})\n`;
  });
}

return [{ json: { report, commits_count: commits.length, issues_count: issues.length, prs_count: mergedPRs.length } }];
